<?php
namespace App\Http\Controllers;use App\Models\{ComparisonRun,ProjectProfile,Report,Survey};use App\Services\ReportSnapshotService;use Barryvdh\DomPDF\Facade\Pdf;use Carbon\Carbon;use Illuminate\Http\Request;use Illuminate\View\View;use Symfony\Component\HttpFoundation\StreamedResponse;
class ReportController extends Controller{public function index(Request $r):View{abort_unless($r->user()->can('dashboard.view'),403);$reports=Report::with(['survey.floor.building','creator'])->latest('generated_at')->paginate(25);$surveys=Survey::with('floor.building')->latest()->get();$comparisons=ComparisonRun::with(['baseline','followup'])->latest()->get();return view('reports.index',compact('reports','surveys','comparisons'));}public function store(Request $r,ReportSnapshotService $service){abort_unless($r->user()->can('reports.generate'),403);$d=$r->validate(['title'=>'required|string|max:180','report_type'=>'required|in:survey,comparison,stakeholder','survey_id'=>'nullable|required_if:report_type,survey|exists:surveys,id','comparison_run_id'=>'nullable|required_if:report_type,comparison|exists:comparison_runs,id','period_start'=>'required|date','period_end'=>'required|date|after_or_equal:period_start']);$survey=isset($d['survey_id'])?Survey::with(['floor.building','floorPlan'])->findOrFail($d['survey_id']):null;$comparison=isset($d['comparison_run_id'])?ComparisonRun::findOrFail($d['comparison_run_id']):null;$from=Carbon::parse($d['period_start']);$to=Carbon::parse($d['period_end']);$snapshot=$service->build($survey,$comparison,$from,$to);$report=Report::create(['project_profile_id'=>ProjectProfile::where('is_active',true)->value('id'),'survey_id'=>$survey?->id,'comparison_run_id'=>$comparison?->id,'created_by'=>$r->user()->id,'title'=>$d['title'],'report_type'=>$d['report_type'],'status'=>'ready','period_start'=>$from,'period_end'=>$to,'filters'=>[],'data_sources'=>['measured','imported','controller','user_reported','estimated'],'limitations'=>array_values(array_filter(['Simulated measurements are excluded from technical calculations.',$survey&&!data_get($snapshot,'survey.coverage_percent')?'No completed heat map was available for this period.':null])),'snapshot'=>$snapshot,'methodology_version'=>'1.0','generated_at'=>now()]);return response()->json($report,201);}public function preview(Request $r,Report $report):View{abort_unless($r->user()->can('dashboard.view'),403);return view('reports.preview',compact('report'));}public function pdf(Request $r,Report $report){abort_unless($r->user()->can('reports.generate'),403);$name='signalgrid-report-'.$report->id.'.pdf';$pdf=Pdf::loadView('reports.pdf',compact('report'))->setPaper('a4','portrait');$report->exports()->create(['requested_by'=>$r->user()->id,'format'=>'pdf','status'=>'ready','file_name'=>$name,'completed_at'=>now()]);return $pdf->download($name);}public function csv(Request $r,Report $report):StreamedResponse{abort_unless($r->user()->can('reports.generate'),403);$name='signalgrid-report-'.$report->id.'.csv';$report->exports()->create(['requested_by'=>$r->user()->id,'format'=>'csv','status'=>'ready','file_name'=>$name,'completed_at'=>now()]);return response()->streamDownload(function()use($report){$out=fopen('php://output','w');fputcsv($out,['section','metric','value']);foreach($this->flatten($report->snapshot) as[$section,$metric,$value])fputcsv($out,[$section,$metric,$value]);fclose($out);},$name,['Content-Type'=>'text/csv']);}private function flatten(array $data,string $prefix=''):array{$rows=[];foreach($data as$key=>$value){$path=$prefix?$prefix.'.'.$key:(string)$key;if(is_array($value))$rows=array_merge($rows,$this->flatten($value,$path));else{$parts=explode('.',$path);$metric=array_pop($parts);$rows[]=[implode('.',$parts),$metric,is_bool($value)?($value?'true':'false'):$value];}}return$rows;}}
